  "pairs": [
    {"reference_id": "R3", "candidate_id": "C3", "target_relation": "different", "reference_claim_ids": ["R3.S2"], "reference_evidence": "as the person puts down one glass, it disappears", "candidate_evidence": "Spray bottle handle nozzle mechanism alters structure rapidly while cleaning cloth materializes and dematerializes nearby.", "basis": "explicit_separation", "reason_ko": "기준 항목은 내려놓던 유리잔(glass)이 사라지는 현상을 지적하지만 후보는 스프레이 병의 구조 변화 및 청소용 천의 생성/소멸을 지적하여 문제 대상과 상호작용 개체가 명확히 다릅니다.", "separation_basis": "different_entity"},
    {"reference_id": "R3", "candidate_id": "C5", "target_relation": "different", "reference_claim_ids": ["R3.S2"], "reference_evidence": "as the person puts down one glass, it disappears", "candidate_evidence": "스프레이 병이 초반에는 투명한 몸체에 작은 흰 라벨만 보이다가 중반(3초 이후)부터 병 전체가 파란색 액체/라벨로 크게 변해 보이며", "basis": "explicit_separation", "reason_ko": "기준 항목은 유리잔의 소멸 현상인 반면 후보는 스프레이 병 라벨 및 액체 색상 변동을 지적하여 불만 대상 개체가 다릅니다.", "separation_basis": "different_entity"},
    {"reference_id": "R3", "candidate_id": "C7", "target_relation": "different", "reference_claim_ids": ["R3.S2"], "reference_evidence": "as the person puts down one glass, it disappears", "candidate_evidence": "The spray bottle's shape, nozzle, and liquid level morph and warp as the person interacts with it.", "basis": "explicit_separation", "reason_ko": "기준 항목의 대상은 내려놓는 유리잔의 소멸인 데 비해 후보는 사람이 다루는 스프레이 병의 형태, 노즐, 수위 변형을 지적하므로 대상 개체가 상이합니다.", "separation_basis": "different_entity"},
    {"reference_id": "R3", "candidate_id": "C8", "target_relation": "different", "reference_claim_ids": ["R3.S2"], "reference_evidence": "as the person puts down one glass, it disappears", "candidate_evidence": "분무기 트리거/노즐 부분의 파란색 영역 형태와 색 분포가 프레임마다 불안정하게 변함.", "basis": "explicit_separation", "reason_ko": "기준 항목은 유리잔이 사라지는 불만이며, 후보는 분무기 트리거/노즐의 형태와 색상 불안정을 다루어 완전히 다른 대상을 지적합니다.", "separation_basis": "different_entity"},
    {"reference_id": "R3", "candidate_id": "C9", "target_relation": "different", "reference_claim_ids": ["R3.S2"], "reference_evidence": "as the person puts down one glass, it disappears", "candidate_evidence": "흰색 천/행주가 프레임마다 위치와 형태가 크게 달라짐.", "basis": "explicit_separation", "reason_ko": "기준 항목은 유리잔의 소멸에 관한 것이고, 후보는 창턱 위 흰색 천/행주의 위치 및 형태 변동을 지적하므로 문제 대상이 서로 다릅니다.", "separation_basis": "different_entity"},
    {"reference_id": "R3", "candidate_id": "C11", "target_relation": "different", "reference_claim_ids": ["R3.S2"], "reference_evidence": "as the person puts down one glass, it disappears", "candidate_evidence": "Spray bottle head shifts shape and liquid level jitters", "basis": "explicit_separation", "reason_ko": "기준 항목의 불만 대상은 유리잔이지만, 후보의 불만 대상은 스프레이 병 헤드 및 액체 수위이므로 대상 개체가 다릅니다.", "separation_basis": "different_entity"},
    {"reference_id": "R3", "candidate_id": "C12", "target_relation": "different", "reference_claim_ids": ["R3.S2"], "reference_evidence": "as the person puts down one glass, it disappears", "candidate_evidence": "초기 프레임들(3.58~4.33초)에서는 분무기 노즐/트리거가 짙은 파랑 단색이었으나, 4.58초 이후 프레임에서 트리거가 밝은 파란색과 흰색이 결합된 다른 형태로 변함.", "basis": "explicit_separation", "reason_ko": "기준 항목은 내려놓는 유리잔이 사라지는 현상인 반면 후보는 분무기 노즐/트리거 형태 및 색상 변화를 문제 삼고 있어 대상이 구별됩니다.", "separation_basis": "different_entity"},
    {"reference_id": "R3", "candidate_id": "C13", "target_relation": "different", "reference_claim_ids": ["R3.S2"], "reference_evidence": "as the person puts down one glass, it disappears", "candidate_evidence": "천이 처음에는 분무기 노즐 쪽(상단)에 들려 있다가, 이후 프레임에서 카운터 위에 놓인 형태, 다시 손으로 닦는 형태로 위치와 형태가 불안정하게 변동함.", "basis": "explicit_separation", "reason_ko": "기준 항목의 불만은 유리잔 소멸인 반면 후보는 손에 든 천/행주의 위치와 형태 불안정을 다루고 있어 대상이 명확히 다릅니다.", "separation_basis": "different_entity"}
  ]
}

